<template><div class="app-container"><h1 class="sr-only">角色与功能权限</h1>
  <el-form :inline="true" v-show="showSearch" label-width="68px"><el-form-item label="角色名称"><el-input v-model="query.name" placeholder="请输入角色名称" clearable style="width:240px" /></el-form-item><el-form-item label="权限字符"><el-input v-model="query.key" placeholder="请输入权限字符" clearable style="width:240px" /></el-form-item><el-form-item label="状态"><el-select v-model="query.status" placeholder="角色状态" clearable style="width:180px"><el-option label="正常" value="0" /><el-option label="停用" value="1" /></el-select></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="load">搜索</el-button><el-button icon="Refresh" @click="resetQuery">重置</el-button></el-form-item></el-form>
  <el-row :gutter="10" class="mb8"><el-col :span="1.5"><el-button type="primary" plain icon="Plus" @click="open()">新增</el-button></el-col><el-col :span="1.5"><el-button type="success" plain icon="Edit" :disabled="selected.length!==1 || selected[0]?.accountTier==='ADMIN'" @click="open(selected[0])">修改</el-button></el-col><el-col :span="1.5"><el-button type="danger" plain icon="Delete" :disabled="!selected.length || selected.some(x=>x.builtin)" @click="removeSelected">删除</el-button></el-col><right-toolbar v-model:showSearch="showSearch" @queryTable="load" /></el-row>
  <el-table :data="filteredRows" v-loading="loading" @selection-change="selected=$event"><el-table-column type="selection" width="55" align="center" /><el-table-column prop="roleId" label="角色编号" width="100" /><el-table-column prop="roleName" label="角色名称" min-width="150" show-overflow-tooltip /><el-table-column prop="roleKey" label="权限字符" min-width="150" show-overflow-tooltip /><el-table-column label="所属等级" width="120"><template #default="{row}">{{tierLabels[row.accountTier]}}</template></el-table-column><el-table-column label="功能范围" min-width="260" show-overflow-tooltip><template #default="{row}">{{row.allowedModules.map(x=>moduleLabels[x]).join('、') || '未授权'}}</template></el-table-column><el-table-column label="状态" width="90" align="center"><template #default="{row}"><el-switch :model-value="row.status" active-value="0" inactive-value="1" :disabled="row.builtin" @change="value=>changeStatus(row,value)" /></template></el-table-column><el-table-column label="操作" width="160" align="center" class-name="small-padding fixed-width"><template #default="{row}"><el-tooltip content="修改" placement="top"><el-button link type="primary" icon="Edit" aria-label="编辑权限" :disabled="row.accountTier==='ADMIN'" @click="open(row)" /></el-tooltip><el-tooltip content="删除" placement="top"><el-button link type="primary" icon="Delete" aria-label="删除" :disabled="row.builtin" @click="remove(row)" /></el-tooltip><el-tooltip content="功能权限" placement="top"><el-button link type="primary" icon="CircleCheck" aria-label="功能权限" :disabled="row.accountTier==='ADMIN'" @click="open(row)" /></el-tooltip></template></el-table-column></el-table>
  <el-dialog v-model="visible" :title="form.roleId?'编辑角色权限':'新增角色'" width="650px" class="access-dialog" append-to-body :close-on-click-modal="false" destroy-on-close>
    <el-form ref="formRef" :model="form" :rules="rules" label-width="120px"><el-form-item label="角色名称" prop="roleName"><el-input v-model="form.roleName" maxlength="30" /></el-form-item><el-form-item label="权限标识" prop="roleKey"><el-input v-model="form.roleKey" :disabled="!!form.roleId" placeholder="如 drilling_observer" maxlength="64" /></el-form-item><el-form-item label="所属等级"><el-select v-model="form.accountTier" :disabled="!!form.roleId" @change="form.menuIds=[]"><el-option label="工程师" value="ENGINEER" /><el-option label="游客" value="GUEST" /></el-select></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status" :disabled="form.builtin"><el-radio value="0">正常</el-radio><el-radio value="1">停用</el-radio></el-radio-group></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="500" /></el-form-item>
    <template v-if="form.accountTier==='ENGINEER'"><el-form-item label="数据范围" prop="dataScope"><el-select v-model="form.dataScope"><el-option v-for="(label,key) in scopeLabels" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item v-if="form.dataScope==='2'" label="自定义部门"><el-tree :data="departmentTree" show-checkbox check-strictly node-key="deptId" default-expand-all :default-checked-keys="form.deptIds" :props="{label:'deptName',children:'children'}" @check="(_,state)=>form.deptIds=state.checkedKeys"/></el-form-item></template>
    <el-divider>可访问功能模块</el-divider><el-checkbox-group v-model="form.allowedModules"><el-checkbox v-for="(name,key) in moduleLabels" :key="key" :value="key">{{name}}</el-checkbox></el-checkbox-group>
    <template v-if="form.accountTier==='ENGINEER'"><el-divider>操作权限</el-divider><div class="access-toolbar"><el-button size="small" @click="selectAll(true)">全选操作</el-button><el-button size="small" @click="selectAll(false)">清空</el-button></div><el-tree class="tree-border role-permission-tree" ref="treeRef" :data="permissionTree" node-key="id" show-checkbox default-expand-all :default-checked-keys="form.menuIds" :props="{label:'label',children:'children'}" @check="checked" /></template>
    <el-alert v-else title="游客角色只授予模块演示权限，不授予真实井场数据和操作权限。" type="info" :closable="false" style="margin-top:18px" />
    </el-form><template #footer><el-button type="primary" :loading="saving" @click="save">确 定</el-button><el-button @click="visible=false">取 消</el-button></template>
  </el-dialog>
</div></template>
<script setup>
import { reactive,ref,computed,nextTick,onMounted } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import './access.css'
import { accessOptions,listRoles,saveRole,deleteRole } from '@/api/access'
import { scopeLabels,treeRows } from '@/api/organization'
import { moduleLabels,tierLabels } from '@/security/access'
const showSearch=ref(true),selected=ref([]),query=reactive({name:'',key:'',status:''})
const rows=ref([]),options=reactive({permissions:[],departments:[]}),loading=ref(false),saving=ref(false),visible=ref(false),formRef=ref(),treeRef=ref(),form=reactive({})
const filteredRows=computed(()=>rows.value.filter(r=>(!query.name||r.roleName.includes(query.name))&&(!query.key||r.roleKey.includes(query.key))&&(!query.status||r.status===query.status)))
function resetQuery(){query.name='';query.key='';query.status='';load()}
async function changeStatus(row,status){try{await saveRole({...row,status});await load()}catch(e){console.error(e)}}
async function removeSelected(){try{await ElMessageBox.confirm('确认删除选中的角色？','提示',{type:'warning'});for(const row of selected.value)await deleteRole(row.roleId);await load()}catch(e){if(e!=='cancel'&&e!=='close')console.error(e)}}
const rules={roleName:[{required:true,message:'请输入角色名称',trigger:'blur'}],roleKey:[{required:true,message:'请输入角色权限标识',trigger:'blur'}]}
const departmentTree=computed(()=>treeRows(options.departments).map(function disable(n,blocked=false){const disabled=blocked||n.status!=='0';return {...n,disabled,children:n.children.map(c=>disable(c,disabled))}}))
const groups={block:'区块',field:'井场',well:'井',survey:'测斜数据',config:'工程配置',file:'文件',alarm:'报警',prediction:'预测',model:'模型',training:'模型更新',train:'训练',anticollision:'防碰',replanning:'再规划'}
const permissionTree=computed(()=>{const map=new Map();for(const p of options.permissions){const key=p.perms.split(':')[1];if(!map.has(key))map.set(key,{id:`group-${key}`,label:groups[key]||key,children:[]});map.get(key).children.push({id:p.menuId,label:`${p.menuName}（${p.perms}）`})}return [...map.values()]})
function checked(){form.menuIds=treeRef.value.getCheckedKeys().filter(x=>typeof x==='number')}
function selectAll(value){treeRef.value.setCheckedKeys(value?options.permissions.map(x=>x.menuId):[]);checked()}
async function load(){loading.value=true;try{rows.value=(await listRoles()).data}finally{loading.value=false}}
async function open(row){Object.assign(options,(await accessOptions()).data);Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{roleName:'',roleKey:'',accountTier:'ENGINEER',status:'0',allowedModules:[],menuIds:[],dataScope:'6',deptIds:[],remark:''},row?JSON.parse(JSON.stringify(row)):{});visible.value=true;await nextTick();treeRef.value?.setCheckedKeys(form.menuIds)}
async function save(){if(!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{await saveRole(form);visible.value=false;ElMessage.success('角色及功能权限已保存');await load()}catch{ /* API interceptor displays the validation error; keep the form open. */ }finally{saving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`删除角色 ${row.roleName}？`,'删除角色',{type:'warning'});await deleteRole(row.roleId);ElMessage.success('角色已删除');await load()}catch(e){if(e!=='cancel'&&e!=='close')console.error(e)}}
onMounted(load)
</script>
